            if (transparencyInput) decisions.transparency = parseInt(transparencyInput.value);

            var empathyInput = document.getElementById('empathyInput');
            if (empathyInput) decisions.empathy = parseInt(empathyInput.value);

            var stakeholderInput = document.getElementById('stakeholderInput');
            if (stakeholderInput) decisions.stakeholderFocus = parseInt(stakeholderInput.value);

            var budgetInput = document.getElementById('budgetInput');
            if (budgetInput) decisions.budget = parseInt(budgetInput.value);

            if (!decisions.speed || decisions.speed < 1 || decisions.speed > 10) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('speed_warning'), 'warning'
                );
                return false;
            }

            if (!decisions.budget || decisions.budget < 10000 || decisions.budget > 200000) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_warning'), 'warning'
                );
                return false;
            }

            var _st = window.mySimulation && window.mySimulation.state; var remaining = _st && _st.domainState ? _st.domainState.crisisBudget : 500000;
            if (decisions.budget > remaining) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('budget_exceed'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var phase = state.currentPeriod;

            var speedEffect = 0;
            var transparencyEffect = 0;
            var empathyEffect = 0;
            var stakeholderEffect = 0;
            var eventModifier = 0;

            if (phase === 1) {
                speedEffect = (d.speed >= 8) ? 15 : (d.speed >= 6) ? 10 : (d.speed >= 4) ? 3 : -5;
                transparencyEffect = (d.transparency - 5) * 1.2;
                empathyEffect = (d.empathy - 5) * 1.5;
                stakeholderEffect = (d.stakeholderFocus >= 7) ? 5 : (d.stakeholderFocus >= 4) ? 2 : -3;

                ds.speedDimension = (d.speed >= 8) ? 15 : (d.speed >= 6) ? 12 : (d.speed >= 4) ? 8 : 4;
            } else if (phase === 2) {
                speedEffect = (d.speed >= 7) ? 12 : (d.speed >= 5) ? 6 : -3;
                transparencyEffect = (d.transparency - 5) * 2.0;
                empathyEffect = (d.empathy - 5) * 2.5;
                stakeholderEffect = (d.stakeholderFocus >= 7) ? 8 : (d.stakeholderFocus >= 4) ? 3 : -5;
            } else if (phase === 3) {
                speedEffect = (d.speed - 5) * 1.0;
                transparencyEffect = (d.transparency >= 7) ? 10 : (d.transparency >= 5) ? 4 : -6;
                empathyEffect = (d.empathy >= 7) ? 10 : (d.empathy >= 5) ? 4 : -8;
                stakeholderEffect = (d.stakeholderFocus >= 6) ? 10 : (d.stakeholderFocus >= 4) ? 4 : -6;

                var eventIdx = Math.floor(Math.random() * this.EVENTS.length);
                ds.activeEvent = this.EVENTS[eventIdx];
                ds.activeEventIndex = eventIdx;

                if (eventIdx === 3) {
                    eventModifier = -8;
                } else if (eventIdx === 4) {
                    eventModifier = (ds.stakeholderHistory.length > 0 && d.stakeholderFocus >= 7) ? -2 : -12;
                } else if (eventIdx === 0) {
                    eventModifier = (d.empathy >= 7 && d.transparency >= 7) ? 5 : -5;
                } else if (eventIdx === 1) {
                    eventModifier = (d.speed <= 3) ? -6 : -2;
                } else {
                    eventModifier = (d.transparency >= 7) ? 3 : -5;
                }
            } else if (phase === 4) {
                speedEffect = (d.speed - 5) * 0.8;
                transparencyEffect = (d.transparency >= 8) ? 12 : (d.transparency >= 6) ? 6 : -4;
                empathyEffect = (d.empathy >= 8) ? 14 : (d.empathy >= 6) ? 7 : -6;
                stakeholderEffect = (d.stakeholderFocus >= 7) ? 8 : (d.stakeholderFocus >= 4) ? 3 : -5;

                if (ds.activeEventIndex === 3) {
                    eventModifier = (d.transparency >= 8) ? 4 : -6;
                } else if (ds.activeEventIndex === 4) {
                    eventModifier = (d.empathy >= 8 && d.stakeholderFocus >= 7) ? 6 : -8;
                }
            } else {
                speedEffect = (d.speed >= 4 && d.speed <= 7) ? 6 : -3;
                transparencyEffect = (d.transparency >= 8) ? 12 : (d.transparency >= 6) ? 6 : -4;
                empathyEffect = (d.empathy >= 7) ? 8 : (d.empathy >= 5) ? 4 : -4;
                stakeholderEffect = (d.stakeholderFocus >= 6) ? 8 : 2;
            }

            var consistencyBonus = 0;
            if (ds.previousTransparency > 0) {
                var transDiff = Math.abs(d.transparency - ds.previousTransparency);
                var empDiff = Math.abs(d.empathy - ds.previousEmpathy);
                if (transDiff <= 2 && empDiff <= 2) {
                    consistencyBonus = 4;
                } else if (transDiff >= 5 || empDiff >= 5) {
                    consistencyBonus = -6;
                }
            }

            var budgetEffect = 0;
            var budgetRatio = d.budget / 200000;
            if (phase <= 2) {
                budgetEffect = budgetRatio * 5;
            } else if (phase === 3) {
                budgetEffect = budgetRatio * 8;
            } else if (phase === 4) {
                budgetEffect = budgetRatio * 6;
            } else {
                budgetEffect = budgetRatio * 4;
            }

            var sentimentChange = speedEffect + transparencyEffect + empathyEffect + eventModifier + consistencyBonus + budgetEffect;

            var trustChange = (empathyEffect * 0.6) + (transparencyEffect * 0.8) + (consistencyBonus * 0.5) + (budgetEffect * 0.3);

            var phaseStakeholderScore = stakeholderEffect + (d.empathy >= 7 ? 3 : 0) + (d.stakeholderFocus >= 7 ? 4 : 0);

            ds.sentiment = Math.max(-100, Math.min(100, ds.sentiment + sentimentChange));
            ds.brandTrust = Math.max(0, Math.min(100, ds.brandTrust + trustChange));
            ds.stakeholderScore += phaseStakeholderScore;
            ds.crisisBudget -= d.budget;
            ds.totalSpent += d.budget;

            ds.sentimentHistory.push(Math.round(ds.sentiment));
            ds.trustHistory.push(Math.round(ds.brandTrust));
            ds.stakeholderHistory.push(phaseStakeholderScore);
            ds.budgetHistory.push(d.budget);

            ds.previousTransparency = d.transparency;
            ds.previousEmpathy = d.empathy;

            if (phase >= 2) {
                ds.coherenceDimension += (consistencyBonus > 0 ? 5 : (consistencyBonus < 0 ? -3 : 1));
            }
            ds.stakeholderDimension += phaseStakeholderScore;

            if (phase === 5) {
                var recoveryQ = 0;
                recoveryQ += (d.transparency >= 8) ? 6 : (d.transparency >= 6) ? 3 : 0;
                recoveryQ += (d.empathy >= 7) ? 5 : (d.empathy >= 5) ? 2 : 0;
                recoveryQ += (d.speed >= 4 && d.speed <= 7) ? 4 : 0;
                ds.recoveryDimension = recoveryQ;
            }

            // platform score: same speed plus coherence plus stakeholder plus sentiment plus recovery
            // dimensions, each capped as in getPerformanceSummary, so the 0 to 100 total lines up
            // with that final verdict every round
            var scoreSpeed = ds.speedDimension || 0;
            var scoreCoherence = Math.max(0, Math.min(25, 12 + (ds.coherenceDimension || 0)));
            var scoreStakeholder = Math.max(0, Math.min(20, 10 + Math.round((ds.stakeholderDimension || 0) * 0.5)));
            var scoreSentiment = Math.max(0, Math.min(25, Math.round(((ds.sentiment || -65) + 65) * 0.25 + 12)));
            var scoreRecovery = Math.max(0, Math.min(15, ds.recoveryDimension || 0));
            var overallScore = Math.max(0, Math.min(100, scoreSpeed + scoreCoherence + scoreStakeholder + scoreSentiment + scoreRecovery));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            var phaseScore = Math.round(sentimentChange + trustChange + phaseStakeholderScore);
            ds.phaseScores.push(phaseScore);

            var self = this;
            var nextPeriod = (state.currentPeriod || 1) + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod });
            }, 500);

            return {
                period: phase,
                sentimentChange: Math.round(sentimentChange),
                trustChange: Math.round(trustChange),
                stakeholderGain: Math.round(phaseStakeholderScore),
                sentiment: Math.round(ds.sentiment),
                brandTrust: Math.round(ds.brandTrust),
                budgetSpent: d.budget,
                phaseScore: phaseScore,
                eventModifier: Math.round(eventModifier)
            };
        }

