        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var ds = last.domainState || {};

            var speedScore = ds.speedDimension || 0;
            var coherenceBase = ds.coherenceDimension || 0;
            var coherenceScore = Math.max(0, Math.min(25, 12 + coherenceBase));
            var stakeholderBase = ds.stakeholderDimension || 0;
            var stakeholderScore = Math.max(0, Math.min(20, 10 + Math.round(stakeholderBase * 0.5)));

            var sentimentStart = -65;
            var sentimentEnd = ds.sentiment || -65;
            var sentimentRecovery = sentimentEnd - sentimentStart;
            var sentimentScore = Math.max(0, Math.min(25, Math.round(sentimentRecovery * 0.25 + 12)));

            var recoveryScore = Math.max(0, Math.min(15, ds.recoveryDimension || 0));

            var totalScore = speedScore + coherenceScore + stakeholderScore + sentimentScore + recoveryScore;

            var performance = window.mySimulation.t('perf_novice');
            if (totalScore >= 80) performance = window.mySimulation.t('perf_master');
            else if (totalScore >= 65) performance = window.mySimulation.t('perf_skilled');
            else if (totalScore >= 50) performance = window.mySimulation.t('perf_competent');
            else if (totalScore >= 35) performance = window.mySimulation.t('perf_developing');

            var insights = [];
            if (speedScore >= 12) {
                insights.push(window.mySimulation.t('insight_fast_response'));
            } else {
                insights.push(window.mySimulation.t('insight_slow_response'));
            }
            if (coherenceScore >= 18) {
                insights.push(window.mySimulation.t('insight_coherent_strategy'));
            } else {
                insights.push(window.mySimulation.t('insight_inconsistent_strategy'));
            }
            if (sentimentEnd > -10) {
                insights.push(window.mySimulation.t('insight_sentiment_recovery'));
            } else {
                insights.push(window.mySimulation.t('insight_sentiment_negative'));
            }
            if (stakeholderScore >= 14) {
                insights.push(window.mySimulation.t('insight_stakeholder_effective'));
            }
            if (recoveryScore >= 10) {
                insights.push(window.mySimulation.t('insight_recovery_plan'));
            }

            return {
                totalScore: totalScore,
                speedScore: speedScore,
                coherenceScore: coherenceScore,
                stakeholderScore: stakeholderScore,
                sentimentScore: sentimentScore,
                recoveryScore: recoveryScore,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var phase = state.currentPeriod;

            if (phase === 1 && results.sentimentChange < 5) {
