            }
            if (results.sentimentChange < 0) {
                return window.mySimulation.t('hint_negative');
            }
            if (state.domainState.crisisBudget < 100000) {
                return window.mySimulation.t('hint_budget');
            }
            if (results.trustChange < 0) {
                return window.mySimulation.t('hint_trust');
            }
            if (results.sentimentChange > 15) {
                return window.mySimulation.t('hint_good');
            }
            return null;
        }

