        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.PHASES.length - 1);
            var phase = this.PHASES[idx];

            var titleEl = document.getElementById('phaseTitle');
            if (titleEl) {
                var titleKey = phase.titleKey;
                var translated = window.mySimulation ? window.mySimulation.t(titleKey) : '';
                titleEl.textContent = translated || titleEl.textContent;
            }

            var iconEl = document.getElementById('phaseIcon');
            if (iconEl) iconEl.textContent = phase.icon;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = window.mySimulation ? window.mySimulation.t(phase.briefingKey) : '';

            var mentionEl = document.getElementById('mentionVolume');
            if (mentionEl) mentionEl.textContent = window.mySimulation ? window.mySimulation.t(phase.mentionsKey) : '';

            var mediaEl = document.getElementById('mediaStatus');
            if (mediaEl) mediaEl.textContent = window.mySimulation ? window.mySimulation.t(phase.mediaKey) : '';

            var viralEl = document.getElementById('viralStatus');
            if (viralEl) viralEl.textContent = window.mySimulation ? window.mySimulation.t(phase.viralKey) : '';

            var eventPanel = document.getElementById('eventPanel');
            var eventText = document.getElementById('eventText');
            if (eventPanel && eventText) {
                var ds = state.domainState || (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {};
                if (ds.activeEvent && (state.currentPeriod === 4 || state.currentPeriod === 5)) {
                    eventPanel.style.display = 'block';
                    eventText.innerHTML = window.mySimulation ? window.mySimulation.t('event' + ds.activeEventIndex + '_text') : ds.activeEvent;
                } else {
                    eventPanel.style.display = 'none';
                }
            }

            var sentInd = document.getElementById('sentimentIndicator');
            if (sentInd && (state.domainState = state.domainState || (window.mySimulation&&window.mySimulation.state&&window.mySimulation.state.domainState))) {
                var sh = state.domainState.sentimentHistory || [];
                if (sh.length >= 2) {
                    var diff = sh[sh.length - 1] - sh[sh.length - 2];
                    sentInd.textContent = (diff >= 0 ? '+' : '') + diff + ' from last phase';
                    sentInd.style.color = diff >= 0 ? '#34d399' : '#ef4444';
                }
            }

            var trustInd = document.getElementById('trustIndicator');
            if (trustInd && (state.domainState = state.domainState || (window.mySimulation&&window.mySimulation.state&&window.mySimulation.state.domainState))) {
                var th = state.domainState.trustHistory || [];
                if (th.length >= 2) {
                    var tdiff = th[th.length - 1] - th[th.length - 2];
                    trustInd.textContent = (tdiff >= 0 ? '+' : '') + tdiff + ' from last phase';
                    trustInd.style.color = tdiff >= 0 ? '#34d399' : '#ef4444';
                }
            }
        }
    }

